238	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
239	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
240	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
241	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
242	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
243	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
244	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
245	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
246	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
247	     * assigned (see {@link #requireUniqueIdentity}).
248	     *
249	     * @param ownerFieldsDto the incoming owner payload, mutated in place
250	     * @throws MissingOwnerFieldsException if any required field is missing or blank
251	     */
252	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
253	        normalizeAddress(ownerFieldsDto);
254	        validateRequiredFields(ownerFieldsDto);
255	        validatePostcode(ownerFieldsDto);
256	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
257	        ownerFieldsDto.setTelephone(telephone);
258	        requireCityHasCapacity(ownerFieldsDto.getCity());
259	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
260	        ownerFieldsDto.setRegistrationDate(registrationDate);
261	        requireDailyLimitNotReached(registrationDate);
262	        normalizeEmail(ownerFieldsDto);
263	    }
264	
265	    /**
266	     * Normalizes an owner's address to its canonical stored form and writes it back onto the payload. The canonical
267	     * form (see {@link AddressNormalizer#normalize}) is what gets stored and returned as {@code address} and what every
268	     * address comparison uses; a {@code null} input yields an empty string, so a blank result is uniformly treated as a
269	     * missing address by the required-field check that follows. The payload is mutated in place so the caller can map
270	     * and save it directly.
271	     *
272	     * @param ownerFieldsDto the incoming owner payload, mutated in place
273	     */
274	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
275	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
276	    }
277	
278	    /**
279	     * Normalizes an owner's optional email to its canonical stored form and writes it back onto the payload. The
280	     * canonical form (see {@link EmailNormalizer#normalize}) is what gets stored and returned as {@code email} and what
281	     * every email comparison uses; a missing (blank or {@code null}) email is left untouched. The payload is mutated in
282	     * place so the caller can map and save it directly.
283	     *
284	     * @param ownerFieldsDto the incoming owner payload, mutated in place
285	     */
286	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
287	        ownerFieldsDto.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
288	    }
289	
290	    /**
291	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
292	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
293	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day. A supplied date
294	     * later than the current server date is rejected.
295	     *
296	     * @param ownerFieldsDto the incoming owner payload
297	     * @return the effective registration date rolled forward onto a business day
298	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
299	     */
300	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
301	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
302	        if (effective == null) {
303	            effective = LocalDate.now();
304	        }
305	        else if (effective.isAfter(LocalDate.now())) {
306	            throw new FutureRegistrationDateException(
307	                "the registration date must not be later than the current server date");
308	        }
309	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
310	            effective = effective.plusDays(1);
311	        }
312	        return effective;
313	    }
314	
315	    /**
316	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
317	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
318	     * further owner may be created for that day.
319	     *
320	     * @param registrationDate the adjusted business-day registration date of the owner being created
321	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
322	     */
323	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
324	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
325	            throw new DailyOwnerLimitExceededException(
326	                "the maximum number of owners for today has already been reached");
327	        }
328	    }
329	
330	    /**
331	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
332	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
333	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
334	     * warning threshold) so both express the same per-day count in one place.
335	     *
336	     * @param registrationDate the adjusted business-day registration date to count owners for
337	     * @return the number of existing owners registered on that day
338	     */
339	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
340	        return this.clinicService.findAllOwners().stream()
341	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
342	            .count();
343	    }
344	
345	    /**
346	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
347	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
348	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
349	     * reflects only owners that predate it.
350	     *
351	     * @param registrationDate the adjusted business-day registration date of the owner being created
352	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
353	     */
354	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
355	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
356	    }
357	
358	    /**
359	     * Counts how many existing owners already share the given owner's first and last name, compared
360	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
361	     * create; it is zero when the owner's name is unique.
362	     *
363	     * @param owner the newly mapped owner about to be saved
364	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
365	     */
366	    private int countNamesakes(Owner owner) {
367	        String firstName = owner.getFirstName();
368	        String lastName = owner.getLastName();
369	        return (int) this.clinicService.findAllOwners().stream()
370	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
371	                && lastName.equalsIgnoreCase(existing.getLastName()))
372	            .count();
373	    }
374	
375	    /**
376	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
377	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
378	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
379	     *
380	     * @param ownerFieldsDto the owner payload to validate
381	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
382	     */
383	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
384	        List<String> missingFields = new ArrayList<>();
385	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
386	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
387	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
388	        requireText(missingFields, "city", ownerFieldsDto.getCity());
389	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
390	        if (!missingFields.isEmpty()) {
391	            throw new MissingOwnerFieldsException(missingFields);
392	        }
393	    }
394	
395	    private void requireText(List<String> missingFields, String fieldName, String value) {
396	        if (value == null || value.isBlank()) {
397	            missingFields.add(fieldName);
398	        }
399	    }
400	
401	    /**
402	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
403	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
404	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
405	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
406	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
407	     *
408	     * @param ownerFieldsDto the incoming owner payload
409	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
410	     */
411	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
412	        String postcode = ownerFieldsDto.getPostcode();
413	        if (postcode == null) {
414	            return;
415	        }
416	        Region region = Region.forCity(ownerFieldsDto.getCity());
417	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
418	            throw new InvalidPostcodeException(
419	                "postcode " + postcode + " is not valid for the city's region " + region.name());
420	        }
421	    }
422	
423	    /**
424	     * Rejects creating an owner whose whole derived {@code identityKey} (see
425	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
426	     * duplicate only when its normalized telephone, email and {@code householdId} all match another owner's. It runs
427	     * after the household id has been assigned, so the key reflects the household the owner belongs to. Owners that
428	     * share only their household (same last name and postcode, different telephone) are not caught here but by the
429	     * separate household-duplicate guard (see {@link #requireHouseholdNotDuplicate}).
430	     *
431	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
432	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
433	     */
434	    private void requireUniqueIdentity(Owner owner) {
435	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
436	        boolean inUse = this.clinicService.findAllOwners().stream()
437	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
438	        if (inUse) {
439	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
440	        }
441	    }
442	
443	    /**
444	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared both the hard-duplicate
445	     * guard (see {@link #requireUniqueIdentity}) and the household-duplicate guard (see
446	     * {@link #requireHouseholdNotDuplicate}), so it is still being created; this only records a warning. A declared
447	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
448	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
449	     * duplicate when some existing owner shares its last name (compared case-insensitively) and its postcode but
450	     * carries a different telephone. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
451	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
452	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
453	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
454	     *
455	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
456	     * @param ownerFieldsDto the incoming owner payload
457	     */
458	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
459	        owner.setPossibleDuplicate(false);
460	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
461	            return;
462	        }
463	        String postcode = owner.getPostcode();
464	        if (postcode == null || postcode.isBlank()) {
465	            return;
466	        }
467	        String lastName = owner.getLastName();
468	        String telephone = owner.getTelephone();
469	        for (Owner existing : this.clinicService.findAllOwners()) {
470	            if (lastName.equalsIgnoreCase(existing.getLastName())
471	                && postcode.equals(existing.getPostcode())
472	                && !java.util.Objects.equals(telephone, existing.getTelephone())) {
473	                owner.setPossibleDuplicate(true);
474	                owner.setPossibleDuplicateOf(existing.getId());
475	                return;
476	            }
477	        }
478	    }
479	
480	    /**
481	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
482	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
483	     *
484	     * @param city the city of the owner being created
485	     * @throws OwnerCityFullException if the city already contains 50 or more owners
486	     */
487	    private void requireCityHasCapacity(String city) {
488	        long cityOwners = this.clinicService.findAllOwners().stream()
489	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
490	            .count();
491	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
492	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
493	        }
494	    }
495	
496	    /**
497	     * Assigns the shared {@code householdId} for a newly mapped owner. The identifier is derived deterministically from
498	     * the owner's last name and postcode (see {@link HouseholdResolver#deriveHouseholdId}), so every owner sharing
499	     * those two fields resolves to the same stable value automatically, regardless of creation order and without any
500	     * explicit linking. An owner created without a postcode has no household and keeps a {@code null} identifier, so
501	     * such owners never match one another as a household.
502	     *
503	     * @param owner the newly mapped owner about to be saved
504	     */
505	    private void assignHouseholdId(Owner owner) {
506	        String postcode = owner.getPostcode();
507	        if (postcode == null || postcode.isBlank()) {
508	            owner.setHouseholdId(null);
509	            return;
510	        }
511	        owner.setHouseholdId(householdResolver.deriveHouseholdId(owner.getLastName(), postcode));
512	    }
513	
514	    /**
515	     * Rejects creating an owner that would join an existing household it has not declared. Because the household is
516	     * keyed on the last name and postcode (see {@link #assignHouseholdId}), any existing owner carrying the same
517	     * derived {@code householdId} is a member of the same household. A second such owner is a household duplicate and is
518	     * rejected, unless the payload sets {@code sharesHousehold} to {@code true}, which declares the owner a genuine
519	     * household member and lets the create proceed. An owner with no household ({@code null} householdId, i.e. created
520	     * without a postcode) can never be a household duplicate.
521	     *
522	     * @param owner          the newly mapped owner about to be saved, with its household id already assigned
523	     * @param ownerFieldsDto the incoming owner payload
524	     * @throws DuplicateOwnerException if an existing owner already belongs to this household and the create did not
525	     *                                 declare {@code sharesHousehold}
526	     */
527	    private void requireHouseholdNotDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
528	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
529	            return;
530	        }
531	        String householdId = owner.getHouseholdId();
532	        if (householdId == null) {
533	            return;
534	        }
535	        boolean sharedByExisting = this.clinicService.findAllOwners().stream()
536	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
537	        if (sharedByExisting) {
538	            throw new DuplicateOwnerException("an owner in the same household already exists");
539	        }
540	    }
541	
542	    /**
543	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
544	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
545	     * household is counted as a household of one.
546	     *
547	     * @param owner the owner whose household size should be resolved
548	     */
549	    private void populateHouseholdMemberCount(Owner owner) {
550	        String householdId = owner.getHouseholdId();
551	        if (householdId == null) {
552	            owner.setHouseholdMemberCount(1);
553	            return;
554	        }
555	        long members = this.clinicService.findAllOwners().stream()
556	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
557	            .count();
558	        owner.setHouseholdMemberCount((int) members);
559	    }
560	
561	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
562	    @Override
563	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
564	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
565	        if (currentOwner == null) {
566	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
567	        }
568	        validatePostcode(ownerFieldsDto);
569	        currentOwner.setAddress(ownerFieldsDto.getAddress());
570	        currentOwner.setCity(ownerFieldsDto.getCity());
571	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
572	        currentOwner.setLastName(ownerFieldsDto.getLastName());
573	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
574	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
575	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
576	        this.clinicService.saveOwner(currentOwner);
577	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
578	    }
579	
580	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
581	    @Transactional
582	    @Override
583	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
584	        Owner owner = this.clinicService.findOwnerById(ownerId);
585	        if (owner == null) {
586	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
587	        }
588	        this.clinicService.deleteOwner(owner);
589	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
590	    }
591	
592	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
593	    @Override
594	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
595	        Owner owner = this.clinicService.findOwnerById(ownerId);
596	        if (owner == null) {
597	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
598	        }
599	        HttpHeaders headers = new HttpHeaders();
600	        Pet pet = petMapper.toPet(petFieldsDto);
601	        owner.setId(ownerId);
602	        pet.setOwner(owner);
603	        pet.getType().setName(null);
604	        this.clinicService.savePet(pet);
605	        PetDto petDto = petMapper.toPetDto(pet);
606	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
607	            .buildAndExpand(pet.getId()).toUri());
608	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
609	    }
610	
611	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
612	    @Override
613	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
614	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
615	        if (currentOwner != null) {
616	            Pet currentPet = this.clinicService.findPetById(petId);
617	            if (currentPet != null) {
618	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
619	                currentPet.setName(petFieldsDto.getName());
620	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
621	                this.clinicService.savePet(currentPet);
622	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
623	            }
624	        }
625	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
626	    }
627	
628	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
629	    @Override
630	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
631	        HttpHeaders headers = new HttpHeaders();
632	        Visit visit = visitMapper.toVisit(visitFieldsDto);
633	        Pet pet = new Pet();
634	        pet.setId(petId);
635	        visit.setPet(pet);
636	        this.clinicService.saveVisit(visit);
637	        VisitDto visitDto = visitMapper.toVisitDto(visit);
638	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
639	            .buildAndExpand(visit.getId()).toUri());
640	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
641	    }
642	
643	
644	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
645	    @Override
646	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
647	        Owner owner = this.clinicService.findOwnerById(ownerId);
648	        if (owner != null) {
649	            Pet pet = owner.getPet(petId);
650	            if (pet != null) {
651	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
652	            }
653	        }
654	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
655	    }
656	}
