1	package org.springframework.samples.petclinic.acceptance;
2	
3	import org.junit.jupiter.api.Test;
4	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
5	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
6	import tools.jackson.databind.node.ObjectNode;
7	
8	/** address-structured: structured addressLine1/city/postcode is accepted and normalized (
9	 * rules: upper-case, collapse whitespace, expand ST->STREET), and 'address' is the composed
10	 * normalized string. The flat 'address' form stays accepted (backward-compatible). */
11	class AcceptanceTest extends AcceptanceBase {
12	
13		@Test
14		void coreNormalizesAndComposesStructuredAddress() throws Exception {
15			ObjectNode o = structuredOwner();
